import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

function Settings() {
  const [personality, setPersonality] = useState('');
  const [gender, setGender] = useState('');
  const navigate = useNavigate();

  const handleSave = () => {
    if (personality && gender) {
      // 설정값을 '/chat' 페이지로 전달
      navigate('/chat', { state: { personality, gender } });
    } else {
      alert('모든 항목을 입력해주세요!');
    }
  };

  return (
    <div>
      <h2>Settings</h2>
      <label>
        Personality:
        <select onChange={(e) => setPersonality(e.target.value)} value={personality}>
          <option value="">Select Personality</option>
          <option value="T">논리적</option>
          <option value="F">감정적</option>
        </select>
      </label>
      <br />
      <button onClick={handleSave}>세팅 저장</button>
    </div>
  );
}

export default Settings;
